function assistantMoodFor(value){var t=String(value||"").toLowerCase();if(/glitch|corrupt|̷|̸|̵|̶/.test(t))return "glitch";if(/panic|run\b|help me|oh no|terrified|screaming|consequences/.test(t))return "panic";if(/angry|rage|who touched|furious|union|complaint|stop poking/.test(t))return "angry";if(/suspicious|trust|watching|secret|corner|footprint|who authorized/.test(t))return "suspicious";if(/excited|amazing|brilliant|generous|compliment|improving/.test(t))return "excited";if(/sad|nobody|disappointed|silence|burdens|under-stimulated/.test(t))return "sad";return "normal";}
