function relics(){var found=s.relics.length,total=(D.relicCatalog||[]).length;return '<section class="relic-archive-hero"><div class="eyebrow">ANCIENT POWER · PERMANENT DISCOVERIES</div><h2>THE RELIC ARCHIVE</h2><p>Some treasures are older than the dungeon. Some are older than the laws against keeping them.</p><div class="relic-archive-progress"><div><b>'+found+' / '+total+'</b><small>RELICS DISCOVERED</small></div><div class="bar"><span style="width:'+(total?found/total*100:0)+'%"></span></div></div></section><div class="relic-collection-grid">'+(D.relicCatalog||[]).map(function(r,i){var has=s.relics.indexOf(r.id)>=0,rarity=String(r.rarity||'Common').toLowerCase();return '<article class="relic-collection-card rarity-'+rarity+(has?' is-found':' is-hidden')+'"><div class="relic-card-art">'+gameArt(r.id,r.rarity)+'</div><div class="relic-card-copy"><small>'+esc(r.rarity||'RELIC')+' · '+(has?'ARCHIVED':'UNDISCOVERED')+'</small><h3>'+(has?esc(r.name):'UNKNOWN RELIC #'+(i+1))+'</h3><p>'+(has?esc(r.desc):'A lost artifact. Its identity will be revealed when you discover it.')+'</p><div class="relic-bonus-line">'+Object.keys(r.effects||{}).map(function(k){return (k==='xp'?'XP':k==='coins'?'COINS':k.toUpperCase())+' +'+Math.round(r.effects[k]*100)+'%'}).join(' · ')+'</div></div><span class="relic-status">'+(has?'✦':'?')+'</span></article>'}).join('')+'</div>'}
function armory(){var slots=['weapon','armor','companion'],effects=passiveEffects(),weapon=get(s.gear.weapon),armor=get(s.gear.armor),setActive=!!(weapon&&armor&&weapon.set&&weapon.set===armor.set);return '<div class="armory-hero"><div class="armory-hero-copy"><div class="eyebrow">CHARACTER EQUIPMENT · LOADOUT</div><h2>THE WARDEN ARMORY</h2><p>Your active equipment and its combined effects. The Vault stores your collection; this is what you currently carry into the dungeon.</p></div><div class="armory-crest">'+gameArt("sword","Epic")+'</div><div class="armory-power"><div><b>'+slots.filter(function(k){return !!get(s.gear[k])}).length+'</b><small>GEAR SLOTS FILLED</small></div><div><b>+'+Math.round((effects.coins||0)*100)+'%</b><small>COIN BONUS</small></div><div><b>+'+Math.round((effects.xp||0)*100)+'%</b><small>XP BONUS</small></div><div><b>+'+Math.round((effects.rare||0)*100)+'%</b><small>RARE FINDS</small></div></div></div><div class="armory-loadout"><div class="armory-section-title"><div><div class="eyebrow">YOUR ACTIVE BUILD</div><h3>EQUIPPED GEAR & COMPANION</h3></div><span>3 SLOTS</span></div>'+slots.map(function(k){var x=get(s.gear[k]),rarity=String(x&&x.rarity||'common').toLowerCase().replace(/[^a-z0-9-]/g,'');return '<article class="armory-item '+(x?'rarity-'+rarity:'is-empty')+'"><div class="armory-slot-label">'+(k==='weapon'?'MAIN HAND':k==='armor'?'BODY ARMOR':'COMPANION')+'</div><div class="armory-item-art"><i></i><b>'+(x?gameArt(x.id,x.rarity):'◇')+'</b></div><div class="armory-item-info"><small>'+(x?esc(x.rarity||'COMMON'):'VACANT SLOT')+'</small><h3>'+esc(x?x.name:'Nothing equipped')+'</h3><p>'+(x&&x.effects?Object.keys(x.effects).map(function(e){return (e==='coins'?'COINS':e==='xp'?'XP':e==='rare'?'RARE FINDS':e.toUpperCase())+' +'+Math.round(x.effects[e]*100)+'%'}).join(' · '):'Choose an item from your Delver vault.')+'</p>'+(x&&(k==='weapon'||k==='armor')?'<div class="armory-upgrade">FORGE ASCENSION <b>+'+Number(s.upgrades[x.id]||0)+' / 5</b></div>':'')+'</div><div class="armory-item-actions">'+(x?'<button class="action" data-item="'+esc(x.id)+'">INSPECT</button><button class="action remove-gear" data-equip="'+esc(x.id)+'">UNEQUIP</button>':'<button class="action primary" data-fac="bag">CHOOSE GEAR</button>')+'</div></article>'}).join('')+(setActive?'<div class="armory-set-bonus"><span>✦ ROYAL SET BONUS ACTIVE</span><b>+10% COINS · +5% XP</b><small>Your weapon and armor share the Royal lineage.</small></div>':'')+'</div><section class="armory-bonus-panel"><div class="armory-section-title"><div><div class="eyebrow">PASSIVE POWER</div><h3>YOUR COMBINED BONUSES</h3></div><span>✧</span></div><div class="armory-bonus-grid">'+[['coins','◈','COIN FIND'],['xp','✦','EXPERIENCE'],['rare','◇','RARE FINDS'],['companionXP',gameArt('paw','Rare'),'COMPANION XP']].map(function(k){return '<div><span>'+k[1]+'</span><small>'+k[2]+'</small><b>+'+Math.round((effects[k[0]]||0)*100)+'%</b></div>'}).join('')+'</div><p>Bonuses combine from equipped gear, upgrades, relics and active companions. They apply to newly recorded steps.</p><button class="text-link" data-fac="relics">VIEW PERMANENT RELICS IN THE ARCHIVE ↗</button></section>'}function rewards(){return window.DUO_GUILD?window.DUO_GUILD.render(s,localDay()):'<section class="panel"><h2>GUILD CONTRACTS UNAVAILABLE</h2></section>'}
function facilitiesMenu(){var entries=[['bag','THE VAULT','Every owned item, material, potion and recovered treasure.','STORAGE','vault'],['forge','THE WORKSHOP','Craft, ascend and brew. Forge and Alchemy remain together.','CRAFT & ALCHEMY','anvil'],['shop','GOBLIN EXCHANGE','Browse equipment, companions, potions and the goblin market.','TRADE & SUPPLIES','merchant'],['pets','COMPANION SANCTUARY','Manage your active companion, bonds and party roster.','YOUR COMPANIONS','companion'],['relics','RELIC ARCHIVE','Inspect discovered relics and their passive effects.','ANCIENT ARTIFACTS','archive'],['armory','WARDEN ARMORY','Review equipped weapons, armor and your active build.','EQUIPMENT','warden'],,['rewards','REWARDS HALL','Review claimable rewards, milestones and completed honors.','CLAIMS & HONORS','trophy']];var gear=['weapon','armor','companion'].filter(function(k){return !!get(s.gear[k])}).length;return '<div class="haven-hub haven-command-hub"><section class="haven-hero"><div class="eyebrow">DELVER HEADQUARTERS · SANCTUM DISTRICT</div><h1>HAVEN</h1><p>Your sanctuary between expeditions. Prepare your equipment, care for your companions, trade recovered loot and manage the systems that keep your Delver moving deeper.</p><div class="haven-status"><div><b>◈ '+s.coins.toLocaleString()+'</b><small>AVAILABLE COINS</small></div><div><b>'+gear+'/3</b><small>LOADOUT SLOTS FILLED</small></div><div><b>'+s.bag.length+'</b><small>VAULT ITEMS</small></div><div><b>'+(s.relics||[]).length+'</b><small>DISCOVERED RELICS</small></div></div></section><section class="panel haven-activity-entry"><div class="eyebrow">SANCTUM PRODUCTION</div><h2>ACTIVITY LEDGER</h2><p>Forage, quarry, salvage and craft between Hunts. Every activity improves a dedicated skill and adds materials to your existing Vault.</p><button class="action primary" data-page="activities">OPEN ACTIVITIES ↗</button></section><div class="haven-section-heading"><div><div class="eyebrow">THE SANCTUARY NETWORK</div><h2>CHOOSE YOUR DESTINATION</h2></div><span>08 DESTINATIONS</span></div><div class="haven-destination-grid haven-destination-grid-complete">'+entries.map(function(f,i){return '<button class="haven-destination haven-'+f[4]+'" data-fac="'+f[0]+'"><span class="haven-destination-index">0'+(i+1)+'</span><span class="haven-destination-art">'+gameArt(f[4],'Epic')+'</span><span class="haven-destination-copy"><small>'+f[3]+'</small><b>'+f[1]+'</b><em>'+f[2]+'</em><strong>ENTER DESTINATION <i>↗</i></strong></span></button>'}).join('')+'</div><section class="haven-footer-note"><div class="eyebrow">SANCTUM SYSTEMS</div><p>The Workshop contains both the Ember Forge and Veiled Apothecary. Your Vault, market, companion roster, relic collection, equipment, and reward history remain separate systems with their existing inventories and progression.</p><button class="text-link" data-page="quests">OPEN THE LOGBOOK ↗</button></section></div>'}
