function buy(id){var x=get(id);if(!x)return;if(x.type==='identity'){toast('Identity licenses are available in the identity counter update.');return}if(s.coins<Number(x.price||0)){toast('Not enough coins, Delver.');return}if(x.type==='companion'&&s.bag.indexOf(id)>=0){toast('You already own this companion.');return}s.coins-=Number(x.price||0);if(window.DUO_INVENTORY_ECONOMY)window.DUO_INVENTORY_ECONOMY.record(s,"purchase","Purchased "+displayDelverLabel(x.name),"-"+Number(x.price||0)+" coins");s.bag.push(id);if(x.type==="title")unlockTitle(x.name,"TITLE ACQUIRED","A title license has been added to your earned collection. The System has updated your available identity options.");addNotification("item",displayDelverLabel(x.name),"New acquisition secured in your Vault. The goblin insists the paperwork is legitimate.",String(x.rarity||"COMMON").toUpperCase());document.getElementById('detail').close();render();toast('ACQUIRED: '+displayDelverLabel(x.name))}
