function equip(id){var x=get(id);if(!x||s.bag.indexOf(id)<0)return;if(['weapon','armor','companion'].indexOf(x.type)<0){toast('This item cannot be equipped. The Armory has standards, apparently.');return}var previous=s.gear[x.type];if(x.type==='companion'&&previous)s.companionXPById[previous]=Number(s.companionXP||0);s.gear[x.type]=previous===id?null:id;if(x.type==='companion')s.companionXP=Number(s.companionXPById[s.gear.companion]||0);document.getElementById('detail').close();save();render();toast(s.gear[x.type]?'EQUIPPED: '+x.name:'UNEQUIPPED')}
function usePotion(id){var x=get(id);if(!x||x.type!=='potion')return;var ix=s.bag.indexOf(id);if(ix<0){toast('Potion not found in The Vault. The potion has not developed legs. Yet.');return}var p=x.potion||{},entry={id:id,name:x.name,kind:p.kind||'timed',effect:p.effect||{},activatedAt:Date.now()};if(p.kind==='timed'){entry.endsAt=Date.now()+Number(p.minutes||10)*60000;s.activePotions.push(entry)}else if(p.kind==='achievement'){entry.charges=Number(p.charges||1);s.activePotions.push(entry)}else{entry.kind='steps';entry.remainingSteps=Number(p.steps||2500);s.activePotions.push(entry)}s.bag.splice(ix,1);document.getElementById('detail').close();save();render();toast('POTION ACTIVATED: '+x.name)}
