function upgrade(id){var x=get(id),n=Number(s.upgrades[id]||0),cost=500*(n+1);if(!x||n>=5){toast('Maximum upgrade reached.');return}if(s.coins<cost){toast('You need '+cost+' coins.');return}s.coins-=cost;s.upgrades[id]=n+1;if(window.DUO_INVENTORY_ECONOMY)window.DUO_INVENTORY_ECONOMY.record(s,"upgrade","Upgraded "+x.name,"-"+cost+" coins · rank +"+(n+1));save();render();toast(x.name+' upgraded to +'+(n+1))}
