function openRenameDialog(){var fee=s.name?5000:0,dlg=document.getElementById("rename-dialog");if(!dlg){dlg=document.createElement("dialog");dlg.id="rename-dialog";document.body.appendChild(dlg)}dlg.innerHTML='<button class="close" type="button" data-rename-close aria-label="Close">×</button><div class="eyebrow">DELVER IDENTITY SERVICES</div><h2>'+(fee?"A FRESH ALIAS, IS IT?":"YOUR FIRST NAME — COMPLIMENTARY")+'</h2><blockquote class="rename-ai-comment">“Ah, a naming consultation. Your first one is free because apparently I am running a charity now. Any changes after that will cost you 5,000 coins. I do love a good bribe, by the way. Subtlety is appreciated; large coin purses are more appreciated.”<br><small>— THE SYSTEM, REGISTRAR, AND DEFINITELY NOT A CROOK</small></blockquote><form id="rename-form"><label for="rename-input">YOUR DELVER NAME</label><input id="rename-input" type="text" maxlength="20" autocomplete="off" placeholder="Enter a name worth remembering" value="'+esc(s.name||"")+'" required><p class="rename-price">'+(fee?"COST: ◈ 5,000 COINS":"COST: FREE · FIRST NAME ASSIGNMENT")+'</p><div class="rename-actions"><button class="action secondary" type="button" data-rename-close>NEVER MIND</button><button class="action primary" type="submit">'+(fee?"PAY & CHANGE NAME":"CLAIM MY NAME")+'</button></div></form>';dlg.querySelectorAll("[data-rename-close]").forEach(function(b){b.addEventListener("click",function(){dlg.close()})});dlg.querySelector("#rename-form").addEventListener("submit",function(e){e.preventDefault();var input=dlg.querySelector("#rename-input"),name=input.value.trim();if(!name){input.focus();return}if(name.length>20){toast("Names are limited to 20 characters.");return}if(fee&&s.coins<fee){toast("Not enough coins. The registrar remains tragically incorruptible.");dlg.close();return}if(name===s.name){dlg.close();toast("No change detected. I admire your commitment to paperwork.");return}var commitName=function(){if(fee)s.coins-=fee;s.name=name;save();dlg.close();render();toast(fee?"Name changed. 5,000 coins well spent.":"Your name is now official. Try not to let it go to your head.")};if(AUTH&&AUTH.user&&AUTH.renameCrawlerName){AUTH.renameCrawlerName(name).then(commitName).catch(function(err){toast(err.message||"Could not register that name.");input.focus()})}else{commitName()}});if(typeof dlg.showModal==="function")dlg.showModal();else{dlg.setAttribute("open","");dlg.classList.add("rename-fallback-open")}setTimeout(function(){var input=dlg.querySelector("#rename-input");if(input)input.focus()},80)}
